  const updateCommentMutation = useUpdateComment({
    discussionId,
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'Comment Updated',
        });
      },
    },
  });

  // Note: We rely on the FormDrawer's internal state for isOpen, but we need to
  // clear the success state so the drawer can be reopened if the user tries to edit
  // again (or if we want to show the form again). However, typically after success
  // we might just show the updated list. The user requirement says "Show a success
  // message after saving".

  // To be able to reopen the drawer, we might need to manage the `isDone` prop
  // from the parent or reset it. But looking at CreateComment, it just passes
  // `createCommentMutation.isSuccess`. If the mutation succeeds, `isDone` is true,
  // and the drawer closes. To reopen, we'd need to reset the success state.
  // Since we don't have a parent to control this easily without props, we might need
  // to use a state or assume the parent doesn't need to reopen it immediately.
  // However, a common pattern is to reset the success state when the drawer is about
  // to open again, or just use a local state for the "is success" part if it's complex.
  // Let's stick to the mutation result for simplicity, as in CreateComment.
  // If the user wants to edit again, they might need to refresh or we can add an
  // explicit reset.
  // Actually, let's look at the `useDisclosure` hook in `FormDrawer`. It has `close()`
  // and `open()`. The `isDone` prop calls `close()`.
  // To allow reopening, we should probably manage the `isDone` state manually or
  // accept that it won't reopen until the next render if `isSuccess` is true.
  // A better UX often includes an "Edit" button that reopens the drawer.
  // Let's just pass `updateCommentMutation.isSuccess` for now.

  return (
    <FormDrawer
      isDone={updateCommentMutation.isSuccess}
      triggerButton={
        <Button variant="ghost" size="sm" icon={<Pencil className="size-4" />}>
          Edit
        </Button>
      }
      title="Edit Comment"
      submitButton={
        <Button
          isLoading={updateCommentMutation.isPending}
          form="edit-comment"
          type="submit"
          size="sm"
          disabled={updateCommentMutation.isPending}
        >
          Update
        </Button>
      }
    >
      <Form
        id="edit-comment"
        onSubmit={(values) => {
          updateCommentMutation.mutate({
            commentId,
            data: values,
          });
        }}
        schema={updateCommentInputSchema}
        options={{
          defaultValues: {
            body: initialBody,
          },
        }}
      >
        {({ register, formState }) => (
          <Textarea
            label="Body"
            error={formState.errors['body']}
            registration={register('body')}
          />
        )}
      </Form>
    </FormDrawer>
  );
};

